"use strict";function ChangeUrl(title,url){if(void 0!==history.pushState){var obj={Title:title,Url:url};history.pushState(obj,obj.Title,obj.Url)}else alert("Browser does not support HTML5.")}$(function(){var $sidebar=$("#filterSidebar");$(".btn-filter").on("click",function(){$sidebar.toggleClass("oppend")}),$(document).mouseup(function(e){$sidebar.is(e.target)||0!==$sidebar.has(e.target).length||$sidebar.removeClass("oppend")});var $filters=$("#filtersForm");$filters.find(":input").on("change",function(){var data=$filters.serialize(),url=$filters.data("action");$.ajax({url:url,data:data}).done(function(data){$("#resultsList").html(data)}).fail(function(){console.log("error")})}),$(document).on("click",".directory-pagination .page-link",function(event){event.preventDefault();var url=$(this).data("search");console.log(url),$.ajax({url:url}).done(function(data){$("#resultsList").html(data)}).fail(function(){console.log("error")})})});